('wes-lamp-krx', 'LAMP-KRX-LED', 'LÁMPARA DESTELLANTE LED CAME KRX CON ANTENA', 'CAME', 'acceso', 'Lámpara de señalización vial LED CAME KRX de advertencia visual para apertura y cierre de portones. Fuente luminosa de alta visibilidad diurna y nocturna con antena sintonizada de 433.92 MHz integrada para maximizar el alcance de los mandos a distancia.', '["SKU: LAMP-KRX-LED","Alimentación: Multi-voltaje 24V a 230V AC/DC","Tecnología: LED de alta visibilidad y bajo consumo","Antena integrada: 433.92 MHz de largo alcance","Protección: IP54 para intemperie","Disponibilidad: 6 unidades en inventario físico WES"]'::jsonb, 3450, 'DOP', 'Disponible', 6, 'https://images.unsplash.com/photo-1509391365360-2e959784a276?auto=format&fit=crop&w=960&q=80', true, true, false, false, NULL, 'normal', NULL, '[{"url":"https://images.unsplash.com/photo-1509391365360-2e959784a276?auto=format&fit=crop&w=960&q=80","title":"Lámpara Baliza LED CAME KRX","badge":"Principal","caption":"Lámpara de señalización vial LED con cúpula ámbar y antena integrada"},{"url":"https://sc04.alicdn.com/kf/H8733a0786cb84e018452aa53d4748bccs.jpg_960x960q80.jpg","title":"Circuito LED Multi-Voltaje","badge":"Electrónica","caption":"Placa LED de alto brillo compatible de 24V AC/DC a 230V AC"},{"url":"https://sc04.alicdn.com/kf/H541089cf56e54fcf9bfc4f9a8691647ft.jpg_960x960q80.jpg","title":"Antena 433.92 MHz Incorporada","badge":"Antena RF","caption":"Aumenta la recepción de los mandos a distancia hasta un 40% más"},{"url":"https://sc04.alicdn.com/kf/Ha03773ecd03149afbfbf6f294ff29859i.jpg_960x960q80.jpg","title":"Señalización en Portón en Apertura","badge":"En Operación","caption":"Alerta visual automática de seguridad para vehículos y peatones en la acera"}]'::jsonb, '{"Alimentación":"Multi-voltaje automático (24V AC/DC a 230V AC)","Fuente de Luz":"LED SMD de alto brillo y consumo menor a 1.4W","Antena Receptora":"Sintonizada 433.92 MHz y 868 MHz con terminal de cable coaxial","Material Cúpula":"Policarbonato anti-impacto resistente a rayos solares UV","Grado de Protección":"IP54 para intemperie total contra lluvias torrenciales","Montaje":"Base horizontal o soporte angular lateral para pared","Garantía WES":"2 años oficial CAME"}'::jsonb, NOW())
ON CONFLICT (id) DO UPDATE SET
    codigo = EXCLUDED.codigo,
    nombre = EXCLUDED.nombre,
    marca = EXCLUDED.marca,
    categoria_id = EXCLUDED.categoria_id,
    descripcion = EXCLUDED.descripcion,
    caracteristicas = EXCLUDED.caracteristicas,
    precio = EXCLUDED.precio,
    moneda = EXCLUDED.moneda,
    disponibilidad = EXCLUDED.disponibilidad,
    stock = EXCLUDED.stock,
    imagen_url = EXCLUDED.imagen_url,
    destacado = EXCLUDED.destacado,
    activo = EXCLUDED.activo,
    en_oferta = EXCLUDED.en_oferta,
    novedad = EXCLUDED.novedad,
    precio_anterior = EXCLUDED.precio_anterior,
    tipo_promocion = EXCLUDED.tipo_promocion,
    manual_url = EXCLUDED.manual_url,
    gallery_images = EXCLUDED.gallery_images,
    key_attributes = EXCLUDED.key_attributes,
    updated_at = NOW();

-- ----------------------------------------------------------------------------
-- PASO 6: CONSULTA DE VALIDACIÓN
-- ----------------------------------------------------------------------------
SELECT 
    COUNT(*) AS total_productos_en_base_de_datos,
    COUNT(*) FILTER (WHERE en_oferta = true) AS productos_en_oferta,
    COUNT(*) FILTER (WHERE novedad = true) AS productos_novedades,
    COUNT(*) FILTER (WHERE manual_url IS NOT NULL) AS con_manual_tecnico,
    COUNT(*) FILTER (WHERE gallery_images <> '[]'::jsonb) AS con_galeria_fotos
FROM public.productos;
